import json
import re
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.current_row = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        if tag == 'td':
            self.in_td = True

    def handle_endtag(self, tag):
        if tag == 'td':
            self.in_td = False
        elif tag == 'tr':
            self.rows.append(self.current_row)
            self.current_row = []

    def handle_data(self, data):
        if self.in_td:
            self.current_row.append(data.strip())

# Parse 2001 bulletin table
data = json.load(open('/app/resources/treasury_bulletin_2001_09.json'))
content = data['document']['elements'][187].get('content')

parser = TableParser()
parser.feed(content)

# Print first 15 rows to see structure
print("First 15 rows:")
for i, row in enumerate(parser.rows[:15]):
    print(f"Row {i}: {row[:5]}")  # First 5 columns
